# Coordinates are bounded so both rectangle areas and their union fit int64.
class Rectangle:

    def __init__(self, x0: int, y0: int, x1: int, y1: int):
        self.x0 = x0
        self.y0 = y0
        self.x1 = x1
        self.y1 = y1

def coordinate(value: int) -> int:
    if value < -1000000000 or value > 1000000000:
        raise ValueError
    return value

def make(x0: int, y0: int, x1: int, y1: int) -> Rectangle:
    coordinate(x0)
    coordinate(y0)
    coordinate(x1)
    coordinate(y1)
    if x0 > x1 or y0 > y1:
        raise ValueError
    return Rectangle(x0, y0, x1, y1)

def area(rectangle: Rectangle) -> int:
    return (rectangle.x1 - rectangle.x0) * (rectangle.y1 - rectangle.y0)

def intersection(a: Rectangle, b: Rectangle) -> int:
    width = min(a.x1, b.x1) - max(a.x0, b.x0)
    height = min(a.y1, b.y1) - max(a.y0, b.y0)
    if width <= 0 or height <= 0:
        return 0
    return width * height
